DROP TABLE IF EXISTS `alarm_process`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `alarm_process` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `process_id` varchar(255) NOT NULL,
  `alarm_id` varchar(255) NOT NULL,
  `handler_id` varchar(255) DEFAULT NULL,
  `handler_type` varchar(255) DEFAULT NULL,
  `action` varchar(255) DEFAULT NULL COMMENT '处理动作',
  `result` varchar(255) DEFAULT NULL COMMENT '处理结果',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `process_time` datetime DEFAULT NULL COMMENT '处理时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `process_id` (`process_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='告警处理表';
